def num_subarrays_with_sum(nums, goal):
    n = len(nums)
    count = 0
    for start in range(n):
        total = 0
        for end in range(start, n):
            total += nums[end]                                             # extend the subarray by one and recompute its sum directly
            if total == goal:
                count += 1
    return count


