def num_subarrays_with_sum(nums, goal):
    def at_most(limit):
        if limit < 0:
            return 0
        left = 0
        total = 0
        subarrays = 0
        for right in range(len(nums)):
            total += nums[right]
            while total > limit:
                total -= nums[left]                                         # too much sum, shrink from the left
                left += 1
            subarrays += right - left + 1                                    # every subarray ending at 'right' starting from left..right qualifies
        return subarrays

    return at_most(goal) - at_most(goal - 1)                                # exactly goal = (sum <= goal) minus (sum <= goal - 1)


if __name__ == "__main__":
    print(num_subarrays_with_sum([1, 0, 1, 0, 1], 2))

